package kr.tong.sky;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.robolectric.Shadows.*;import static org.junit.Assert.*;import java.util.concurrent.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=35,packageName="kr.tong.sky") @LooperMode(LooperMode.Mode.PAUSED) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class TripSearchActivityTest {
 public static class TestActivity extends TripSearchActivity {@Override TripSearch.Dataset loadDataset()throws Exception{JSONObject catalog=new JSONObject(java.nio.file.Files.readString(java.nio.file.Path.of(System.getProperty("tongsky.assets"),oz?"asiana-regions.json":"regions.json")));return TripSearch.prepare(java.util.List.of(),catalog,origin,oz);}}
 @Before public void setup(){RuntimeEnvironment.getApplication().deleteDatabase("tong-sky.db");RuntimeEnvironment.getApplication().deleteDatabase("tong-sky-asiana.db");}
 void settle(TripSearchActivity a)throws Exception{for(int i=0;i<4;i++){a.worker.submit(()->{}).get(5,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 @Test public void bothCarriersOpenWithOnlyRegionAndDurationAndThreeResultTypes()throws Exception{
  for(boolean oz:new boolean[]{false,true}){var intent=new Intent(RuntimeEnvironment.getApplication(),TripSearchActivity.class).putExtra("oz",oz).putExtra("origin","ICN");var controller=Robolectric.buildActivity(TestActivity.class,intent).create().start().resume().visible();TripSearchActivity a=controller.get();settle(a);assertEquals("7",a.days.getText().toString());assertEquals("유럽",a.region.getSelectedItem());assertEquals(oz,a.oz);assertEquals(3,a.types.length);assertNotNull(a.result);assertEquals(0,a.result.total());assertTrue(a.empty.getText().toString().contains("저장된 자료"));a.days.setText("10");a.search.performClick();settle(a);assertTrue(a.status.getText().toString().contains("10일"));a.types[2].performClick();assertEquals(2,a.selectedType);assertTrue(a.types[2].isSelected());controller.pause().stop().destroy();assertTrue(a.worker.awaitTermination(5,TimeUnit.SECONDS));}
 }
 @Test public void invalidDurationClearsStaleResultsAndClosedActivityDropsWork()throws Exception{
  var controller=Robolectric.buildActivity(TestActivity.class,new Intent(RuntimeEnvironment.getApplication(),TripSearchActivity.class).putExtra("oz",false)).create().start().resume();TripSearchActivity a=controller.get();settle(a);for(String value:new String[]{"","0","361","-1","7.5"}){a.days.setText(value);a.search.performClick();assertNotNull(a.days.getError());assertNull(a.result);assertEquals(0,a.list.getAdapter().getCount());}controller.pause().stop().destroy();a.search();assertTrue(a.closed);assertTrue(a.worker.awaitTermination(5,TimeUnit.SECONDS));
 }
 @Test public void savedSelectionSurvivesRecreation()throws Exception{
  var controller=Robolectric.buildActivity(TestActivity.class).create().start().resume();TripSearchActivity a=controller.get();settle(a);a.days.setText("10");a.region.setSelection(a.regions.indexOf("미주"));a.types[1].performClick();Bundle state=new Bundle();controller.saveInstanceState(state).pause().stop().destroy();assertTrue(a.worker.awaitTermination(5,TimeUnit.SECONDS));var next=Robolectric.buildActivity(TestActivity.class).create(state).start().resume();TripSearchActivity b=next.get();settle(b);assertEquals("10",b.days.getText().toString());assertEquals("미주",b.region.getSelectedItem());assertEquals(1,b.selectedType);next.pause().stop().destroy();assertTrue(b.worker.awaitTermination(5,TimeUnit.SECONDS));
 }
}
